import{_ as r,o as t,c as o,ah as p}from"./chunks/framework.DjU4PSOm.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"computer/Research/URA/daily/260820 학연생 실험정리.md","filePath":"computer/Research/URA/daily/260820 학연생 실험정리.md"}'),a={name:"computer/Research/URA/daily/260820 학연생 실험정리.md"};function _(i,e,l,h,c,s){return t(),o("div",null,[...e[0]||(e[0]=[p("<p>Watermark (high/low) 구현 방식 차이<br> 김도균/고보민: free line이 low를 넘어서도 조금씩 GC 돌리지 않고, high까지 확 떨어질 때까지 기다렸다가 한 번에 low까지 몰아서 GC<br> 이지원: 기본 구조는 안 바꾸고, 대신 hot/cold 데이터 분리를 추가해서 실험</p><p>실험 결과 (경향)<br> 김도균/고보민: low 값을 낮게 잡으면 GC가 자주 조금씩, 높게 잡으면 드물게 크게 몰아서 일어남<br> 이지원: hot, cold의 경우에 low↔high를 오가는 형식으로 보이는 스파이크 관찰, seq 워크로드에서는 low에서 high까지 아예 도달하지 못하는 현상도 확인됨</p><p>이 실험의 의미<br> 구현 방식이 서로 달라도 watermark가 의도한 대로 GC를 몰아서 처리하는 패턴은 세 명 모두에서 확인됨 — low/high 사이를 오가며 필요할 때만 몰아서 도는 동작이 구현 디테일에 크게 좌우되지 않고 안정적으로 재현됨.</p><p>FIFO 구현 방식 차이<br> 고보민, 이지원: write_seq 관리용 새 큐 자료구조를 별도로 구현<br> 김도균: 기존 p_queue의 정렬 기준을 vpc → write_seq로 교체 (자료구조 추가 없이 정렬 기준만 변경)</p><p>실험 결과 (경향)<br> 세부적 수치까지 동일하지 않지만 유사한 경향 관찰 — 순차 write에서는 greedy·FIFO 차이 없고, 랜덤 write에서는 FIFO 쪽에서 GC 횟수 증가 + tail latency 튀는 패턴이 공통적으로 관찰됨</p><p>이 실험의 의미<br> 구현 방식이 서로 달라도 정책 로직만 같으면 세 명 모두 같은 경향의 결과가 나옴 — FIFO 정책 특성이 구현 디테일보다 정책 자체에 의해 결정된다는 걸 세 개의 독립적인 구현으로 교차검증.</p><p>Watermark (high/low) 구현 방식 차이<br> 김도균/고보민: free line이 low를 넘어서도 조금씩 GC 돌리지 않고, high까지 확 떨어질 때까지 기다렸다가 한 번에 low까지 몰아서 GC<br> 이지원: 기본 구조는 안 바꾸고, 대신 hot/cold 데이터 분리를 추가해서 실험</p><p>실험 결과 (경향)<br> 김도균/고보민: low 값을 낮게 잡으면 GC가 자주 조금씩, 높게 잡으면 드물게 크게 몰아서 일어남<br> 이지원: hot, cold의 경우에 low↔high를 오가는 형식으로 보이는 스파이크 관찰, seq 워크로드에서는 low에서 high까지 아예 도달하지 못하는 현상도 확인됨</p><p>이 실험의 의미<br> 구현 방식이 서로 달라도 watermark가 의도한 대로 GC를 몰아서 처리하는 패턴은 세 명 모두에서 확인됨 — low/high 사이를 오가며 필요할 때만 몰아서 도는 동작이 구현 디테일에 크게 좌우되지 않고 안정적으로 재현됨.</p><p>FIFO 구현 방식 차이<br> 고보민, 이지원: write_seq 관리용 새 큐 자료구조를 별도로 구현<br> 김도균: 기존 p_queue의 정렬 기준을 vpc → write_seq로 교체 (자료구조 추가 없이 정렬 기준만 변경)</p><p>실험 결과 (경향)<br> 세부적 수치까지 동일하지 않지만 유사한 경향 관찰 — 순차 write에서는 greedy·FIFO 차이 없고, 랜덤 write에서는 FIFO 쪽에서 GC 횟수 증가 + tail latency 튀는 패턴이 공통적으로 관찰됨</p><p>이 실험의 의미<br> 구현 방식이 서로 달라도 정책 로직만 같으면 세 명 모두 같은 경향의 결과가 나옴 — FIFO 정책 특성이 구현 디테일보다 정책 자체에 의해 결정된다는 걸 세 개의 독립적인 구현으로 교차검증.</p>",12)])])}const n=r(a,[["render",_]]);export{d as __pageData,n as default};
